package ai.eva.android.probe;
import java.io.*;import java.nio.file.*;import java.util.*;import org.json.*;
public final class ProviderHistoryOpaqueTest {
 public static void main(String[] args)throws Exception{Path root=Files.createTempDirectory("eva-opaque-");try{File home=root.toFile(),out=new File(home,"sessions/2026/11/08");out.mkdirs();String id=UUID.randomUUID().toString();JSONObject user=new JSONObject().put("type","message").put("id","msg_user").put("role","user").put("content",new JSONArray().put(new JSONObject().put("type","input_text").put("text","keep original request")));JSONObject call=new JSONObject().put("type","function_call").put("id","fc_old").put("call_id","call_original").put("name","tool").put("arguments","{}");JSONObject result=new JSONObject().put("type","function_call_output").put("call_id","call_original").put("output","keep tool evidence");JSONArray history=new JSONArray().put(user).put(call).put(result);String raw=new JSONObject().put("type","session_meta").put("payload",new JSONObject().put("id",id).put("model_provider","openai"))+"\n";for(int i=0;i<history.length();i++)raw+=new JSONObject().put("type","response_item").put("payload",history.get(i))+"\n";raw+=new JSONObject().put("type","compacted").put("payload",new JSONObject().put("replacement_history",new JSONArray().put(user).put(new JSONObject().put("type","compaction").put("id","cmp_private").put("encrypted_content","foreign-opaque-secret"))).put("replacement_history_metadata",new JSONArray().put(new JSONObject()).put(new JSONObject())))+"\n";File source=new File(out,"rollout-"+id+".jsonl");Files.write(source.toPath(),raw.getBytes("UTF-8"));JSONObject r=ProviderHistoryProjection.project(home,out,"/root",id,"other",true);if(!r.getBoolean("needed")||r.getJSONObject("audit").getInt("rebuiltPrivateCheckpoints")!=1)throw new AssertionError("no checkpoint rebuild");String path=r.getString("path");List<String> lines=Files.readAllLines(new File(out,path.substring(path.lastIndexOf('/')+1)).toPath());JSONObject cp=new JSONObject(lines.get(lines.size()-1)).getJSONObject("payload");String text=cp.toString();if(text.contains("foreign-opaque-secret")||!text.contains("keep original request")||!text.contains("keep tool evidence")||!text.contains("call_original")||cp.has("replacement_history_metadata"))throw new AssertionError("lost context or retained private checkpoint");if(!new String(Files.readAllBytes(source.toPath()),"UTF-8").equals(raw))throw new AssertionError("original changed");System.out.println("PASS reverse-provider opaque checkpoint reconstructs original messages and paired tool evidence");}finally{try(java.util.stream.Stream<Path> paths=Files.walk(root)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new UncheckedIOException(e);}});}}}
}
